import {stats} from './engine.js';
export function trainerCap(trainer){if(!Number.isInteger(trainer)||trainer<1||trainer>80)throw Error('트레이너 레벨은 1–80 정수입니다.');return Math.min(50,trainer+10)}
export function legalMoves(db,p,state={}){if(!p)return {fast:[],charged:[]};if(state.shadow&&state.purified)throw Error('그림자와 정화는 함께 선택할 수 없습니다.');if(state.shadow&&state.lucky)throw Error('그림자와 반짝반짝은 함께 선택할 수 없습니다.');if((state.shadow||state.purified)&&(!p.shadowAllowed||p.mega))throw Error('이 종·폼에는 현재 데이터상 그림자·정화 분류를 적용할 수 없습니다.');return {fast:p.fast.filter(k=>db.moves[k]?.energy>=0),charged:[...new Set([...p.charged.filter(k=>!['FRUSTRATION','RETURN'].includes(k)),...(state.shadow?['FRUSTRATION']:state.purified?['RETURN']:[])])].filter(k=>db.moves[k]?.energy<0)}}
export function inferLevel(db,p,iv,trainer,observed,state={}){const cap=trainerCap(trainer),cp=Number(observed?.cp),hp=Number(observed?.hp);if(!Number.isInteger(cp)||cp<10||cp>20000)return {status:'missing',levels:[],level:null,cap,message:'CP를 확인하면 개체 레벨을 자동으로 추정합니다.'};const min=state.purified?25:1,levels=[],known=Number(observed?.calculatedLevel);if(Number.isFinite(known)&&known>=min&&known<=cap&&Number.isInteger(known*2)){const exact=stats(db,p,iv,known);if(exact.cp===cp&&exact.h===hp)return {status:'growth',levels:[known],level:known,cap,message:'육성 적용 레벨 '+known};}for(let l=min;l<=cap;l+=.5){const s=stats(db,p,iv,l);if(s.cp===cp&&(!hp||s.h===hp))levels.push(l)}if(levels.length)return {status:levels.length===1?'matched':'range',levels,level:levels.length===1?levels[0]:null,cap,message:levels.length===1?`추정 레벨 ${levels[0]} · CP${hp?'·HP':''} 일치`:`추정 레벨 ${levels[0]}–${levels.at(-1)} · ${levels.length}개 후보`};const boosted=[];for(let l=Math.max(min,cap+.5);l<=Math.min(51,cap+1);l+=.5){const s=stats(db,p,iv,l);if(s.cp===cp&&(!hp||s.h===hp))boosted.push(l)}return {status:boosted.length?'buddy':'mismatch',levels:boosted,level:null,cap,message:boosted.length?`레벨 ${boosted.join('/')} 가능 · 베스트파트너 보너스 확인 필요`:'일치하는 레벨 없음 · 종·폼·IV·CP·HP·트레이너 레벨을 확인하세요.'}}

export function parseCPText(text){const m=text.match(/(?:CP|cp)\s*[:：]?\s*([0-9][0-9, .]{0,8})/);if(!m)return null;const n=Number(m[1].replace(/[^0-9]/g,''));return n>=10&&n<=20000?n:null}

// CP-only local template OCR. Never treats a low-confidence read as a verified value.
function normalize(mask,w,h){let x0=w,y0=h,x1=-1,y1=-1;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(mask[y*w+x]){x0=Math.min(x0,x);x1=Math.max(x1,x);y0=Math.min(y0,y);y1=Math.max(y1,y)}if(x1<0)return null;const out=[];for(let y=0;y<28;y++)for(let x=0;x<18;x++){const sx=Math.min(x1,Math.floor(x0+(x+.5)*(x1-x0+1)/18)),sy=Math.min(y1,Math.floor(y0+(y+.5)*(y1-y0+1)/28));out.push(mask[sy*w+sx]?1:0)}return out}
export function recognizeCP(image,templates){const {width:w,height:h,data}=image,candidates=[];for(const bright of [true,false]){const mask=new Uint8Array(w*h);for(let i=0;i<w*h;i++){const r=data[i*4],g=data[i*4+1],b=data[i*4+2],v=(r+g+b)/3;mask[i]=bright?(v>195&&Math.max(r,g,b)-Math.min(r,g,b)<55):v<85?1:0}const bands=[];let band=null;for(let y=0;y<h;y++){let n=0;for(let x=0;x<w;x++)n+=mask[y*w+x];if(n>w*.035&&n<w*.8){if(!band)band={y0:y,y1:y};else band.y1=y}else if(band){if(band.y1-band.y0>=h*.12)bands.push(band);band=null}}if(band)bands.push(band);for(const {y0,y1} of bands){const cols=[];let c=null;for(let x=0;x<w;x++){let n=0;for(let y=y0;y<=y1;y++)n+=mask[y*w+x];if(n){if(!c)c={x0:x,x1:x};else c.x1=x}else if(c){cols.push(c);c=null}}if(c)cols.push(c);const glyphs=[];for(const {x0,x1} of cols){const gw=x1-x0+1,gh=y1-y0+1;if(gw<gh*.12||gw>gh*1.1||gh<h*.12)continue;const crop=new Uint8Array(gw*gh);for(let y=0;y<gh;y++)for(let x=0;x<gw;x++)crop[y*gw+x]=mask[(y+y0)*w+x+x0];const norm=normalize(crop,gw,gh);if(!norm)continue;let best={score:Infinity,digit:null},second=Infinity;for(const t of templates){const score=norm.reduce((s,v,i)=>s+(v!==t.mask[i]?1:0),0)/norm.length;if(score<best.score){if(best.digit!==t.digit)second=best.score;best={score,digit:t.digit}}else if(t.digit!==best.digit)second=Math.min(second,score)}glyphs.push({...best,x0,x1,margin:second-best.score});}for(let end=glyphs.length;end>0;end--){const digits=[];for(let j=end-1;j>=0&&digits.length<5;j--){const g=glyphs[j];if(g.score>.26||g.digit===null||digits.length&&digits[0].x0-g.x1>(y1-y0)*.7)break;digits.unshift(g)}if(digits.length<2||digits[0].digit==='0')continue;const cp=Number(digits.map(x=>x.digit).join('')),score=digits.reduce((s,x)=>s+x.score,0)/digits.length;if(cp>=10&&cp<=20000)candidates.push({cp,score,digitCount:digits.length});}}}candidates.sort((a,b)=>b.digitCount-a.digitCount||a.score-b.score);const winner=candidates[0];return winner&&winner.score<.2?{...winner,confidence:winner.score<.1?'높음':'확인 필요'}:null}
export function digitTemplates(canvas){const ctx=canvas.getContext('2d',{willReadFrequently:true}),out=[];canvas.width=80;canvas.height=100;for(const font of ['Arial','Roboto','sans-serif'])for(const weight of [400,500,700])for(let digit=0;digit<10;digit++){ctx.fillStyle='#000';ctx.fillRect(0,0,80,100);ctx.fillStyle='#fff';ctx.font=`${weight} 72px ${font}`;ctx.textBaseline='top';ctx.fillText(String(digit),5,5);const im=ctx.getImageData(0,0,80,100),mask=new Uint8Array(8000);for(let i=0;i<8000;i++)mask[i]=im.data[i*4]>150?1:0;out.push({digit:String(digit),mask:normalize(mask,80,100)})}return out}

